#!/usr/bin/env python3
"""Actualiza vera_v2.py con datos reales + streaming SSE."""
import os, base64, shutil
from datetime import datetime

API_DIR = os.path.expanduser('~/Desktop/vela/backend/api')
target = os.path.join(API_DIR, 'vera_v2.py')

if os.path.exists(target):
    backup = target + '.backup_streaming_' + datetime.now().strftime('%H%M%S')
    shutil.copy(target, backup)
    print(f"Backup: {backup}")

with open(target, 'wb') as f:
    f.write(base64.b64decode(""))
print(f"OK actualizado {target}")
print()
print("Reinicia uvicorn (Ctrl+C y vuelve a ejecutar) y prueba:")
print('  curl -N -X POST "http://localhost:8000/api/vera/v2/chat/stream" \\')
print('    -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" \\')
print('    -d \'{"conversation_id": 1, "message": "Hola"}\'')
